package nowork

import (
	"bytes"
	"encoding/hex"
	"encoding/json"
	"net/http"
	"os"
	"strings"
	"testing"
	"time"
)

// testdata/vectors.json is shared by every SDK (generated by the backend delivery module).
type deliveryVectors struct {
	Keys    map[string]json.RawMessage `json:"keys"`
	Signing json.RawMessage            `json:"signing"`
	Vectors []struct {
		Name, Kind, Key, Compact, Plaintext, Ctx, Response, Body, Secret string
		Fail                                                             bool
		Headers                                                          map[string]string
	} `json:"vectors"`
}

func TestDeliveryVectors(t *testing.T) {
	raw, err := os.ReadFile("testdata/vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	var set deliveryVectors
	if err := json.Unmarshal(raw, &set); err != nil {
		t.Fatal(err)
	}
	keys := map[string]*DecryptionKey{}
	for name, jwk := range set.Keys {
		k, err := ParseDecryptionKey(jwk)
		if err != nil {
			t.Fatalf("key %s: %v", name, err)
		}
		keys[name] = k
	}
	all := []*DecryptionKey{keys["rsa"], keys["ec"], keys["x25519"]}
	const iss, aud = "https://account.example.com", "vector-app"
	for _, v := range set.Vectors {
		plain, _, err := DecryptJWE(v.Compact, keys[v.Key])
		if v.Fail {
			if err == nil {
				t.Fatalf("%s: opened", v.Name)
			}
			continue
		}
		if err != nil || string(plain) != v.Plaintext {
			t.Fatalf("%s: %v %s", v.Name, err, plain)
		}
		if again, _, err := DecryptJWE(v.Compact, all...); err != nil || !bytes.Equal(again, plain) {
			t.Fatalf("%s: kid selection among keys failed: %v", v.Name, err)
		}
		switch v.Kind {
		case "id_token":
			claims, err := DecryptIDToken(v.Compact, set.Signing, iss, aud, all...)
			if err != nil || claims["name"] != "旅行者" || claims["nonce"] != "n-vector" {
				t.Fatalf("nested ID token: %v %v", err, claims)
			}
			if _, err := VerifyIDToken(v.Plaintext, set.Signing, iss, "other-app", time.Now()); err == nil {
				t.Fatal("wrong audience accepted")
			}
		case "server":
			out, err := OpenServerData([]byte(v.Response), v.Ctx, keys[v.Key])
			if err != nil || string(out) != v.Plaintext {
				t.Fatalf("server envelope: %v %s", err, out)
			}
			if _, err := OpenServerData([]byte(v.Response), "server:other:whitelist", keys[v.Key]); err == nil {
				t.Fatal("wrong ctx accepted")
			}
			if _, err := OpenServerData([]byte(`{"code":0,"data":{"server":"x"}}`), "", keys[v.Key]); err == nil {
				t.Fatal("a plain response was accepted")
			}
		case "webhook":
			h := http.Header{}
			for k, val := range v.Headers {
				h.Set(k, val)
			}
			if _, err := VerifyWebhook(v.Secret, h, []byte(v.Body), 0); err != nil {
				t.Fatalf("webhook signature: %v", err)
			}
			ev, err := OpenWebhook([]byte(v.Body), keys[v.Key])
			if err != nil || ev.ID != "evt-vector" || !strings.Contains(string(ev.Data), "旅行者") {
				t.Fatalf("webhook envelope: %v", err)
			}
		}
	}
	if _, _, err := DecryptJWE(set.Vectors[0].Compact, keys["ec"]); err == nil {
		t.Fatal("opened with the wrong key")
	}
}

// TestAESKeyUnwrapRFC3394 is RFC 3394 §4.6 (256-bit key data, 256-bit KEK).
func TestAESKeyUnwrapRFC3394(t *testing.T) {
	kek, _ := hex.DecodeString("000102030405060708090A0B0C0D0E0F101112131415161718191A1B1C1D1E1F")
	wrapped, _ := hex.DecodeString("28C9F404C4B810F4CBCCB35CFB87F8263F5786E2D80ED326CBC7F0E71A99F43BFB988B9B7A02DD21")
	want, _ := hex.DecodeString("00112233445566778899AABBCCDDEEFF000102030405060708090A0B0C0D0E0F")
	got, err := aesKeyUnwrap(kek, wrapped)
	if err != nil || !bytes.Equal(got, want) {
		t.Fatalf("unwrap: %v %x", err, got)
	}
	wrapped[0] ^= 1
	if _, err := aesKeyUnwrap(kek, wrapped); err == nil {
		t.Fatal("a corrupted wrap was accepted")
	}
}
